/**
 * @module useZerarEstoque
 *
 * Hook para zerar estoque de um produto individual ou de um setor inteiro
 * para fins de recontagem física.
 *
 * Chama as RPCs `zerar_estoque_produto` e `zerar_estoque_setor` — definidas em
 * supabase/migrations/20260623120000_zerar_estoque_recontagem.sql.
 *
 * Contrato de API:
 *   - zerarProduto(produtoMasterId, lojaId) → ZerarProdutoResult
 *   - zerarSetor(setorNome, lojaId) → ZerarSetorResult
 *   - isZerando: boolean
 *
 * Regras (spec .harness/spec/zerar-estoque-recontagem/spec.md):
 *   - R6: loja_id NUNCA hardcoded — vem por parâmetro (chamador usa StoreContext)
 *   - R8: idempotente — produto com saldo 0 é no-op (a RPC garante)
 *   - R9: acesso restrito a admin — gate na UI (não aqui)
 */

import { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';

// ─── Tipos públicos ────────────────────────────────────────────────────────────

/** Resultado de `zerarProduto`. Espelha o jsonb retornado pela RPC. */
export interface ZerarProdutoResult {
  ok: boolean;
  noop?: boolean;
  saldo_anterior?: number;
  saldo_novo?: number;
  lotes_zerados?: number;
  etiquetas_resetadas?: number;
  erro?: string;
}

/** Resultado de `zerarSetor`. Espelha o jsonb retornado pela RPC. */
export interface ZerarSetorResult {
  ok: boolean;
  setor?: string;
  produtos_no_setor?: number;
  produtos_zerados?: number;
  produtos_noop?: number;
  etiquetas_resetadas?: number;
  lotes_zerados?: number;
  erros?: { produto_master_id: number; erro: string }[];
  erro?: string;
}

// ─── queryKeys a invalidar após zeragem ───────────────────────────────────────
//
// Evidência grep (src/features/produtos/model/useSetores.ts:76):
//   queryKey: ['setores-gestao']
//   — única queryKey React Query na feature produtos; Produtos.page.tsx usa
//     useState + fetchProdutos() manual, logo não tem queryKey invalidável aqui.
//
// Invalidar ['setores-gestao'] força re-fetch da contagem de itens por setor
// na aba Gerenciar logo após a zeragem.

const QUERY_KEYS_TO_INVALIDATE = [['setores-gestao']] as const;

// ─── Hook ─────────────────────────────────────────────────────────────────────

/**
 * Hook de zeragem de estoque para recontagem física.
 *
 * @example
 * ```tsx
 * const { zerarProduto, zerarSetor, isZerando } = useZerarEstoque();
 * const { selectedStore } = useStoreContext();
 *
 * const resultado = await zerarProduto(produto.id, selectedStore.id);
 * if (!resultado.ok) console.error(resultado.erro);
 * ```
 */
export function useZerarEstoque(): {
  zerarProduto: (
    produtoMasterId: number,
    lojaId: number,
  ) => Promise<ZerarProdutoResult>;
  zerarSetor: (
    setorNome: string,
    lojaId: number,
  ) => Promise<ZerarSetorResult>;
  isZerando: boolean;
} {
  const queryClient = useQueryClient();
  const [isZerando, setIsZerando] = useState(false);

  /** Invalida todas as queries React Query afetadas pela zeragem. */
  async function invalidarQueries(): Promise<void> {
    await Promise.all(
      QUERY_KEYS_TO_INVALIDATE.map((key) =>
        queryClient.invalidateQueries({ queryKey: key }),
      ),
    );
  }

  /**
   * Zera o estoque de um produto individual na loja informada.
   *
   * Guard: lojaId ou produtoMasterId inválidos (null/undefined/0/NaN) retorna
   * ok:false sem chamar a RPC.
   */
  async function zerarProduto(
    produtoMasterId: number,
    lojaId: number,
  ): Promise<ZerarProdutoResult> {
    // Guard: entradas inválidas
    if (
      produtoMasterId == null ||
      !Number.isFinite(produtoMasterId) ||
      produtoMasterId <= 0
    ) {
      return { ok: false, erro: 'produtoMasterId inválido.' };
    }
    if (lojaId == null || !Number.isFinite(lojaId) || lojaId <= 0) {
      return { ok: false, erro: 'lojaId inválido.' };
    }

    setIsZerando(true);
    try {
      // RPCs zerar_estoque_produto/zerar_estoque_setor não estão em types.ts ainda
      // (migration 20260623120000 pendente de regeneração de tipos).
      // Padrão do projeto: (supabase.rpc as any) — ver Produtos.page.tsx:376.
      const { data, error } = await (supabase.rpc as any)('zerar_estoque_produto', {
        p_produto_master_id: produtoMasterId,
        p_loja_id: lojaId,
      });

      if (error) {
        return { ok: false, erro: error.message };
      }

      await invalidarQueries();
      return data as ZerarProdutoResult;
    } finally {
      setIsZerando(false);
    }
  }

  /**
   * Zera o estoque de todos os produtos ativos de um setor na loja informada.
   *
   * Guard: setorNome vazio/nulo ou lojaId inválido retorna ok:false sem chamar
   * a RPC.
   */
  async function zerarSetor(
    setorNome: string,
    lojaId: number,
  ): Promise<ZerarSetorResult> {
    // Guard: entradas inválidas
    if (!setorNome || setorNome.trim() === '') {
      return { ok: false, erro: 'setorNome é obrigatório.' };
    }
    if (lojaId == null || !Number.isFinite(lojaId) || lojaId <= 0) {
      return { ok: false, erro: 'lojaId inválido.' };
    }

    setIsZerando(true);
    try {
      // Mesma razão de zerar_estoque_produto: RPC não tipada em types.ts ainda.
      const { data, error } = await (supabase.rpc as any)('zerar_estoque_setor', {
        p_setor_nome: setorNome,
        p_loja_id: lojaId,
      });

      if (error) {
        return { ok: false, erro: error.message };
      }

      await invalidarQueries();
      return data as ZerarSetorResult;
    } finally {
      setIsZerando(false);
    }
  }

  return { zerarProduto, zerarSetor, isZerando };
}

