import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";

// Interface para o item retornado pela RPC
interface RpcSimulacaoItem {
  loja_id: number;
  produto_master_id: number;
  produto_nome: string;
  setor: string;
  minimo_periodo: number;
  quantidade_atual: number;
  fonte: string;
}

// Interface para os dados de loja do Supabase
interface LojaSupabase {
  id: number;
  nome: string;
}

// Interface EXPORTADA para uma linha de produto pivotada
export interface LinhaMinimo {
  produtoMasterId: number;
  produtoNome: string;
  setor: string;
  colunas: Record<number, { minimo: number; atual: number; fonte: string }>;
}

// Interface EXPORTADA para o resultado do hook
export interface UseSimularMinimoPeriodoResult {
  lojas: Array<{ id: number; nome: string }>;
  linhas: LinhaMinimo[];
  totalPorProduto: Record<number, number>;
  isLoading: boolean;
  isError: boolean;
}

export function useSimularMinimoPeriodo(
  diaInicio: number,
  diasCobertura: number
): UseSimularMinimoPeriodoResult {
  // 1. Busca lojas ativas
  const {
    data: lojasData,
    isLoading: isLoadingLojas,
    isError: isErrorLojas,
  } = useQuery<LojaSupabase[]>({
    queryKey: ["lojas-ativas"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("lojas")
        .select("id,nome")
        .eq("ativo", true)
        .order("id");
      if (error) throw error;
      return data;
    },
  });

  // 2. Executa RPC de simulação
  const {
    data: rpcData,
    isLoading: isLoadingRpc,
    isError: isErrorRpc,
  } = useQuery<RpcSimulacaoItem[]>({
    queryKey: ["simular-minimo-periodo", diaInicio, diasCobertura],
    queryFn: async () => {
      const { data, error } = await (supabase.rpc as any)(
        "simular_minimo_periodo",
        { p_dia_inicio: diaInicio, p_dias_cobertura: diasCobertura }
      );
      if (error) throw error;
      return data;
    },
    enabled: diasCobertura >= 1 && diasCobertura <= 7,
  });

  const isLoading = isLoadingLojas || isLoadingRpc;
  const isError = isErrorLojas || isErrorRpc;

  // 3. Retorna dados pivotados
  const lojas: Array<{ id: number; nome: string }> = [];
  const linhas: LinhaMinimo[] = [];
  const totalPorProduto: Record<number, number> = {};

  if (rpcData && lojasData) {
    const lojasMapById = new Map<number, LojaSupabase>();
    lojasData.forEach((loja) => lojasMapById.set(loja.id, loja));

    const linhasMap = new Map<number, LinhaMinimo>();
    const lojasPresentesIds = new Set<number>();

    rpcData.forEach((item) => {
      // Coleta IDs das lojas presentes nos resultados da RPC
      lojasPresentesIds.add(item.loja_id);

      // Calcula o total por produto
      totalPorProduto[item.produto_master_id] =
        (totalPorProduto[item.produto_master_id] || 0) + item.minimo_periodo;

      // Pivota os dados para LinhaMinimo
      let linha = linhasMap.get(item.produto_master_id);
      if (!linha) {
        linha = {
          produtoMasterId: item.produto_master_id,
          produtoNome: item.produto_nome,
          setor: item.setor,
          colunas: {},
        };
        linhasMap.set(item.produto_master_id, linha);
      }
      linha.colunas[item.loja_id] = {
        minimo: item.minimo_periodo,
        atual: item.quantidade_atual,
        fonte: item.fonte,
      };
    });

    // Converte o mapa de linhas para array e ordena
    linhas.push(...Array.from(linhasMap.values()));
    linhas.sort((a, b) => {
      if (a.setor < b.setor) return -1;
      if (a.setor > b.setor) return 1;
      if (a.produtoNome < b.produtoNome) return -1;
      if (a.produtoNome > b.produtoNome) return 1;
      return 0;
    });

    // Converte o set de lojas presentes para array e ordena
    const sortedLojasIds = Array.from(lojasPresentesIds).sort((a, b) => a - b);
    sortedLojasIds.forEach((lojaId) => {
      const lojaInfo = lojasMapById.get(lojaId);
      if (lojaInfo) {
        lojas.push({ id: lojaInfo.id, nome: lojaInfo.nome });
      }
    });
  }

  return {
    lojas,
    linhas,
    totalPorProduto,
    isLoading,
    isError,
  };
}

import React, { useState, useMemo, useEffect } from "react";
import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import { Badge } from "@/shared/ui/badge";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/shared/ui/table";
import { cn } from "@/shared/lib/utils";
import {
  BarChart3,
  CalendarDays,
  Search,
  AlertTriangle,
  Loader2,
} from "lucide-react";
import { useSimularMinimoPeriodo } from "@/features/produtos/model/useSimularMinimoPeriodo";
import { toast } from "react-hot-toast"; // Assumindo react-hot-toast para o toast de erro
// import { useIsMobile } from "@/shared/hooks/use-mobile"; // Não utilizado no layout especificado

// Constante local para os dias da semana (NÃO exportar)
const DIAS_SEMANA = [
  { label: "Dom", dow: 0 },
  { label: "Seg", dow: 1 },
  { label: "Ter", dow: 2 },
  { label: "Qua", dow: 3 },
  { label: "Qui", dow: 4 },
  { label: "Sex", dow: 5 },
  { label: "Sab", dow: 6 },
] as const;

// Mapa label completo dos dias da semana (dentro do componente)
const LABEL_DIA: Record<number, string> = {
  0: "Domingo",
  1: "Segunda",
  2: "Terça",
  3: "Quarta",
  4: "Quinta",
  5: "Sexta",
  6: "Sábado",
};

export function MinimoPorPeriodo() {
  const [diaInicio, setDiaInicio] = useState<number>(new Date().getDay());
  const [diasCobertura, setDiasCobertura] = useState<number>(1);
  const [searchTerm, setSearchTerm] = useState<string>("");

  const { lojas, linhas, totalPorProduto, isLoading, isError } =
    useSimularMinimoPeriodo(diaInicio, diasCobertura);

  // Efeito para mostrar toast de erro
  useEffect(() => {
    if (isError) {
      toast.error("Erro ao calcular mínimos. Tente novamente.");
    }
  }, [isError]);

  // Calcular dias cobertos (circular mod 7)
  const diasCobertos = useMemo(() => {
    const coveredDays: number[] = [];
    for (let i = 0; i < diasCobertura; i++) {
      coveredDays.push((diaInicio + i) % 7);
    }
    return coveredDays;
  }, [diaInicio, diasCobertura]);

  // Filtrar linhas por searchTerm
  const linhasVisiveis = useMemo(() => {
    if (!searchTerm) return linhas;
    const lowerCaseSearchTerm = searchTerm.toLowerCase();
    return linhas.filter(
      (linha) =>
        linha.produtoNome.toLowerCase().includes(lowerCaseSearchTerm) ||
        linha.setor.toLowerCase().includes(lowerCaseSearchTerm)
    );
  }, [linhas, searchTerm]);

  // Obter setores únicos e ordená-los
  const setoresUnicos = useMemo(() => {
    const setores = new Set<string>();
    linhasVisiveis.forEach((linha) => setores.add(linha.setor));
    return Array.from(setores).sort();
  }, [linhasVisiveis]);

  const totalColunas = 2 + lojas.length; // Produto, Total, e cada Loja

  return (
    <div className="p-4 md:p-6 lg:p-8">
      {/* Seção Header */}
      <div className="flex items-center gap-3 mb-6">
        <div className="bg-[#57715B]/10 rounded-2xl p-3">
          <BarChart3 className="h-6 w-6 text-[#57715B]" />
        </div>
        <div>
          <h1 className="text-2xl font-bold tracking-tight">
            Mínimo por Período
          </h1>
          <p className="text-xs uppercase tracking-widest text-muted-foreground">
            PLANEJAMENTO DE REPOSIÇÃO
          </p>
        </div>
      </div>

      {/* Card de Configuração (glass) */}
      <div className="bg-white/60 dark:bg-black/20 backdrop-blur-xl border border-[#57715B]/10 rounded-2xl p-4 md:p-6 space-y-5 mb-6">
        {/* Linha 1: Dia de início da requisição */}
        <div>
          <label className="text-sm font-semibold text-[#57715B] mb-2 block">
            Dia de início da requisição
          </label>
          <div className="flex flex-wrap gap-2">
            {DIAS_SEMANA.map((dia) => (
              <Button
                key={dia.dow}
                size="sm"
                className={cn(
                  "min-h-[44px] rounded-xl",
                  dia.dow === diaInicio
                    ? "bg-[#57715B] text-white shadow-md"
                    : "border border-[#57715B]/20 text-[#57715B] dark:text-[#8FAE94] hover:bg-[#57715B]/5"
                )}
                onClick={() => setDiaInicio(dia.dow)}
              >
                {dia.label}
              </Button>
            ))}
          </div>
        </div>

        {/* Linha 2: Dias de cobertura */}
        <div>
          <label className="text-sm font-semibold text-[#57715B] mb-2 block">
            Dias de cobertura
          </label>
          <div className="flex gap-2">
            {[1, 2, 3, 4, 5, 6, 7].map((n) => (
              <Button
                key={n}
                size="sm"
                className={cn(
                  "min-w-[44px] h-[44px] rounded-xl",
                  n === diasCobertura
                    ? "bg-[#57715B] text-white shadow-md"
                    : "border border-[#57715B]/20 text-[#57715B] dark:text-[#8FAE94] hover:bg-[#57715B]/5"
                )}
                onClick={() => setDiasCobertura(n)}
              >
                {n}
              </Button>
            ))}
          </div>
        </div>

        {/* Linha 3: Badges dos dias cobertos + texto informativo */}
        <div className="flex flex-wrap gap-2 items-center">
          <span className="text-sm text-muted-foreground">
            Período coberto:
          </span>
          {diasCobertos.map((dow) => (
            <Badge
              key={dow}
              className="text-[#57715B] bg-[#57715B]/10 rounded-full px-3 py-1 text-sm font-medium"
            >
              {LABEL_DIA[dow]}
            </Badge>
          ))}
        </div>

        {/* Linha 4: Texto informativo */}
        <p className="text-xs text-muted-foreground italic mt-2 border-l-2 border-[#57715B]/30 pl-3">
          Se a requisição sair na {LABEL_DIA[diaInicio]} e o estoque precisar
          durar {diasCobertura} dia(s), cada loja precisa ter no mínimo as
          quantidades abaixo.
          <br />
          (Consulta apenas — não altera o mínimo automático calculado
          diariamente.)
        </p>
      </div>

      {/* Seção de Busca + Contador */}
      <div className="flex items-center gap-3 mb-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground h-4 w-4" />
          <Input
            placeholder="Buscar produto..."
            className="pl-9 bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <span className="text-xs text-muted-foreground">
          {linhasVisiveis.length} de {linhas.length} produtos
        </span>
      </div>

      {/* Estado de Loading */}
      {isLoading && (
        <div className="bg-white/60 dark:bg-black/20 backdrop-blur-xl border border-[#57715B]/10 rounded-2xl p-8 text-center flex flex-col items-center justify-center space-y-4">
          <Loader2 className="h-10 w-10 animate-spin text-[#57715B] mx-auto block" />
          <p className="text-lg font-semibold text-[#57715B]">
            Calculando mínimos para o período...
          </p>
        </div>
      )}

      {/* Estado de Empty (sem dados mas não loading) */}
      {!isLoading && !isError && linhas.length === 0 && (
        <div className="bg-white/60 dark:bg-black/20 backdrop-blur-xl border border-[#57715B]/10 rounded-2xl p-8 text-center flex flex-col items-center justify-center space-y-4">
          <CalendarDays className="h-16 w-16 opacity-30 text-[#57715B]" />
          <p className="text-lg font-semibold text-[#57715B]">
            Selecione um período acima para ver os mínimos estimados por loja.
          </p>
        </div>
      )}

      {/* Estado de Erro */}
      {!isLoading && isError && (
        <div className="bg-white/60 dark:bg-black/20 backdrop-blur-xl border border-[#57715B]/10 rounded-2xl p-8 text-center flex flex-col items-center justify-center space-y-4">
          <AlertTriangle className="h-10 w-10 text-red-500" />
          <p className="text-lg font-semibold text-red-600 dark:text-red-400">
            Erro ao calcular mínimos. Tente novamente.
          </p>
        </div>
      )}

      {/* Tabela Principal */}
      {!isLoading && !isError && linhasVisiveis.length > 0 && (
        <div className="bg-white/60 dark:bg-black/20 backdrop-blur-xl border border-[#57715B]/10 rounded-2xl overflow-hidden">
          <div className="overflow-x-auto">
            <Table className="min-w-max text-sm">
              <TableHeader>
                <TableRow className="border-b border-[#57715B]/10 hover:bg-transparent">
                  <TableHead className="w-48 min-w-[180px] text-xs font-semibold uppercase tracking-wider text-[#57715B]">
                    Produto
                  </TableHead>
                  <TableHead className="text-center w-20 text-xs font-semibold uppercase tracking-wider text-[#57715B]">
                    Total
                  </TableHead>
                  {lojas.map((loja) => (
                    <TableHead
                      key={loja.id}
                      className="text-center w-24 min-w-[80px] text-xs font-semibold uppercase tracking-wider text-[#57715B]"
                    >
                      {loja.nome}
                    </TableHead>
                  ))}
                </TableRow>
              </TableHeader>
              <TableBody>
                {setoresUnicos.map((setor) => (
                  <React.Fragment key={setor}>
                    <TableRow className="bg-[#57715B]/3 dark:bg-[#57715B]/5 border-none">
                      <TableCell
                        colSpan={totalColunas}
                        className="py-2 px-4 text-xs font-semibold uppercase tracking-widest text-[#57715B]/70"
                      >
                        {setor}
                      </TableCell>
                    </TableRow>
                    {linhasVisiveis
                      .filter((linha) => linha.setor === setor)
                      .map((linha) => (
                        <TableRow
                          key={linha.produtoMasterId}
                          className="border-b border-[#57715B]/5 hover:bg-white/80 dark:hover:bg-[#1A1A1A]/80 transition-colors"
                        >
                          <TableCell className="font-medium text-[#2D362E] dark:text-[#E6DCCF] py-3 px-4">
                            {linha.produtoNome}
                          </TableCell>
                          <TableCell className="text-center font-bold tabular-nums text-[#2D362E] dark:text-[#E6DCCF] py-3">
                            {totalPorProduto[linha.produtoMasterId] ?? 0}
                          </TableCell>
                          {lojas.map((loja) => {
                            const celula = linha.colunas[loja.id];
                            const abaixo =
                              celula && celula.atual < celula.minimo;
                            return (
                              <TableCell key={loja.id} className="text-center py-3">
                                {celula ? (
                                  abaixo ? (
                                    <span className="inline-flex items-center gap-1 text-amber-700 dark:text-amber-400 bg-amber-50/80 dark:bg-amber-900/20 font-semibold rounded-lg px-2 py-1 tabular-nums text-xs">
                                      <AlertTriangle className="h-3 w-3 shrink-0" />
                                      {celula.minimo}
                                    </span>
                                  ) : (
                                    <span className="text-[#2D362E] dark:text-[#E6DCCF] tabular-nums">
                                      {celula.minimo}
                                    </span>
                                  )
                                ) : (
                                  <span className="text-muted-foreground">—</span>
                                )}
                              </TableCell>
                            );
                          })}
                        </TableRow>
                      ))}
                  </React.Fragment>
                ))}
              </TableBody>
            </Table>
          </div>
          {/* Legenda abaixo da tabela */}
          <div className="flex flex-wrap items-center gap-4 text-xs text-muted-foreground p-4 border-t border-[#57715B]/10">
            <span>
              ⚠️ Estoque atual abaixo do mínimo estimado para o período
            </span>
            <div className="hidden sm:flex items-center gap-2">
              <span>Fonte:</span>
              <Badge className="text-gray-700 bg-gray-100 dark:bg-gray-800/20 dark:text-gray-300 rounded-full px-3 py-1 text-xs font-medium">
                histórico
              </Badge>
              <Badge className="text-amber-700 bg-amber-50 dark:bg-amber-900/20 rounded-full px-3 py-1 text-xs font-medium">
                proxy_rede (estimativa pela rede)
              </Badge>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

